\paragraph{严格细节。}下方原定义、公式、定理或算法主体及其标签、编号与技术论证全部保留；首次阅读主线只负责建立入口，不替代严格内容。

\begin{AlgorithmContract}{
  input={光滑目标$f$与梯度、有限初值$x_0$、容差、外层预算$K$及冻结的Wolfe线搜索参数/预算},
  output={最后合法$(\widehat x,\widehat G,\widehat f,\widehat g)$、实际提交轮数$k_{\rm done}$、线搜索试探数$j_{\rm done}$、梯度求值数$g_{\rm done}$、状态与最终诊断},
  preconditions={$K\in\mathbb N_0$、容差为正，线搜索参数合法，$f,\nabla f$接口维数一致且初值在定义域内},
  initialization={置$\widehat x=x_0,\widehat G=I,k_{\rm done}=j_{\rm done}=0$，计算有限初始目标和梯度并记实际求值},
  loop={每轮由上一合法状态形成下降方向，在线搜索预算内试探Wolfe步，再形成梯度与曲率候选},
  update={步长、候选点/梯度和受保护逆Hessian全部通过有限性与正定门禁后才原子提交，并增加$k_{\rm done}$},
  domain={$\widehat G$保持对称正定；已提交目标和梯度有限；曲率不正时只执行预登记阻尼或跳过规则},
  failure={输入或参数非法返回$\mathtt{invalid\_input}$；目标、梯度、方向或曲率更新非有限返回$\mathtt{numerical\_failure}$；Wolfe预算内无合格步返回$\mathtt{line\_search\_failed}$，均保留上一合法状态},
  stop={梯度/联合步长证书、外层预算耗尽、线搜索失败或数值失败时停止},
  budget={至多$K$个原子BFGS轮，每轮线搜索候选上限由输入规则给定并逐次计数},
  status={$\mathtt{converged}$、$\mathtt{budget\_stop}$、$\mathtt{invalid\_input}$、$\mathtt{numerical\_failure}$、$\mathtt{line\_search\_failed}$},
  iterations={$k_{\rm done}$计实际提交轮，$j_{\rm done}$计实际线搜索试探，$g_{\rm done}$计实际梯度求值},
  diagnostics={最终梯度范数、相对步长/目标变化、曲率$s^\mathsf Ty$、阻尼或跳过次数、失败轮/阶段及预算余量},
  complexity={稠密逆BFGS每提交轮$O(d^2)$时间和$O(d^2)$空间，另加实际目标/梯度及线搜索求值成本}
}
\begin{algorithm}[H]
\caption{带曲率保护的逆BFGS方法}\label{alg:V1-C08-bfgs}
\KwIn{目标$f$、梯度、初始点$x_0$}
\KwOut{最后合法$(\widehat x,\widehat G,\widehat f,\widehat g)$；$k_{\rm done},j_{\rm done},g_{\rm done}$；$\mathtt{status}$与诊断}
\KwData{梯度/相对变化容差$\varepsilon$；外层预算$K$；冻结的Wolfe参数、曲率保护规则与每轮线搜索预算}
若维数、容差、预算或线搜索参数非法，返回空结果、计数$0$、$\mathtt{invalid\_input}$及字段诊断\;
置$\widehat x\leftarrow x_0,\widehat G\leftarrow I,k_{\rm done}\leftarrow0,j_{\rm done}\leftarrow0$；计算$\widehat f=f(x_0),\widehat g=\nabla f(x_0)$并置$g_{\rm done}=1$\;
若初始量非有限，返回初值占位、$\mathtt{numerical\_failure}$及初始化诊断；若$\|\widehat g\|\le\varepsilon$，返回$\mathtt{converged}$及零轮梯度证书\;
\While{$k_{\rm done}<K$}{
  形成$p\leftarrow-\widehat G\widehat g$；若非有限或非下降，返回上一合法状态、$\mathtt{numerical\_failure}$及方向诊断\;
  按冻结Wolfe规则逐候选试探并增加$j_{\rm done}$；若预算内无有限合格步，返回上一合法状态、$\mathtt{line\_search\_failed}$及试探诊断\;
  形成$x^+,f^+,g^+$并增加$g_{\rm done}$；若任一非有限，返回上一合法状态、$\mathtt{numerical\_failure}$及候选求值诊断\;
  令$s=x^+-\widehat x,y=g^+-\widehat g$；按预登记规则形成受阻尼的$G^+$或在曲率不足时令$G^+=\widehat G$\;
  若$G^+$非有限、非对称或非正定，返回上一合法状态、$\mathtt{numerical\_failure}$及曲率阶段诊断\;
  原子提交$(\widehat x,\widehat f,\widehat g,\widehat G)\leftarrow(x^+,f^+,g^+,G^+)$并增加$k_{\rm done}$\;
  若梯度范数与预登记相对变化证书满足，返回最后合法状态、$\mathtt{converged}$及联合证书诊断\;
}
返回最后合法状态、$\mathtt{budget\_stop}$及“外层预算耗尽、证书未满足”最终诊断\;
\end{algorithm}
\end{AlgorithmContract}
\SLRobustImplementationStrip{首次阅读只跟踪搜索方向、步长、$s_k,y_k$与曲率条件；实现时再处理曲率保护、线搜索失败和最后合法状态}

\textbf{推导第1步：写出拉格朗日函数。}
\[
\begin{aligned}
\mathcal L(P,w,\lambda)
={}&\sum_{x,y}\widetilde P(x)P(y\mid x)\log P(y\mid x)\\
&+\sum_{i=1}^{n}w_i\{\widetilde E(f_i)-E_P(f_i)\}
+\sum_x\lambda(x)\left\{1-\sum_yP(y\mid x)\right\}.
\end{aligned}
\]

\textbf{推导第2步：对每个概率分量求驻点。}
\[
\frac{\partial\mathcal L}{\partial P(y\mid x)}
=\widetilde P(x)\left[\log P(y\mid x)+1-\sum_iw_if_i(x,y)\right]-\lambda(x)=0.
\]
将只依赖$x$的项合并为$c(x)$，得到
\[
P(y\mid x)=c(x)\exp\left\{\sum_{i=1}^{n}w_if_i(x,y)\right\}.
\]

\textbf{推导第3步：用归一化确定$c(x)$。}
对$y$求和并令结果为1，定义
\[
Z_w(x)=\sum_{y\in\mathcal Y}\exp\left\{\sum_{i=1}^{n}w_if_i(x,y)\right\},
\]
便有
\[
P_w(y\mid x)=\frac{1}{Z_w(x)}
\exp\left\{\sum_{i=1}^{n}w_if_i(x,y)\right\}.
\]
配分函数严格为正，因此条件概率有定义并自动归一化。

\phantomsection\label{struct:V3-C01-CH12}

\textbf{推导第1步：写出精确似然增量。}IIS从当前$w$寻找增量$\delta=(\delta_1,\ldots,\delta_n)^T$。由新旧条件概率之比，
\[
\ell(w+\delta)-\ell(w)
=\sum_i\delta_i\widetilde E(f_i)
-\sum_x\widetilde P(x)\log\sum_yP_w(y\mid x)
e^{\sum_i\delta_i f_i(x,y)}.
\]
对第二项使用$-\log a\geq1-a$，再在$f^\#>0$处使用
\[
e^{\sum_i[f_i/f^\#](\delta_i f^\#)}
\leq\sum_i\frac{f_i}{f^\#}e^{\delta_i f^\#},
\]
得到关于各$\delta_i$可分的完整下界
\[
\begin{aligned}
\ell(w+\delta)-\ell(w)
&\geq B(\delta\mid w)\\
&=\sum_i\delta_i\widetilde E(f_i)
-\sum_{x,y}\widetilde P(x)P_w(y\mid x)
 \sum_{i:f^\#(x,y)>0}\frac{f_i(x,y)}{f^\#(x,y)}
 \bigl(e^{\delta_i f^\#(x,y)}-1\bigr).
\end{aligned}
\]
当$f^\#(x,y)=0$时，非负性推出全部$f_i(x,y)=0$，对应项对$\delta$恒为零，因而不进入内层和式。这一约定同时避免了$0/0$。

\textbf{推导第2步：对分离下界逐坐标求驻点。}记
\[
f^\#(x,y)=\sum_{i=1}^{n}f_i(x,y).
\]
逐项求导得到
\[
\frac{\partial B}{\partial\delta_i}
=\widetilde E(f_i)-
\sum_{x,y}\widetilde P(x)P_w(y\mid x)f_i(x,y)
e^{\delta_i f^\#(x,y)}.
\]
令该导数为零得到尺度方程
\[
\sum_{x,y}\widetilde P(x)P_w(y\mid x)f_i(x,y)
\exp\{\delta_i f^\#(x,y)\}=\widetilde E(f_i).
\]
记左侧为$g_i(\delta_i)$，则
\[
g_i'(\delta_i)=\sum_{x,y}\widetilde P(x)P_w(y\mid x)
f_i(x,y)f^\#(x,y)e^{\delta_i f^\#(x,y)}\geq0.
\]
若模型在某个$f_i>0$且$f^\#>0$的配置上有正质量，则$g_i$严格递增，有限根至多一个。有限根存在还要求$\widetilde E(f_i)$落在$g_i$的值域内；支撑不相容时没有有限根。若$\widetilde E(f_i)=E_{P_w}(f_i)=0$，该坐标不被数据或当前模型识别，应固定而不是声称根唯一；若$\widetilde E(f_i)=0<E_{P_w}(f_i)$，极限解为$\delta_i\to-\infty$，也不存在有限Newton根。

若$f^\#(x,y)\equiv M$且$M>0$为常数，则
\textbf{推导第3步：化简常特征总量情形。}把$M$移出指数，左侧成为$e^{M\delta_i}E_{P_w}(f_i)$，所以
\[
\delta_i=\frac1M\log\frac{\widetilde E(f_i)}{E_{P_w}(f_i)}.
\]
该闭式只适用于分子、分母均为正的可识别坐标；$M=0$时所有特征恒为零，尺度方程不含参数，不能使用上式。

\textbf{零坐标分类。}令$e_i=\widetilde E(f_i)$、$m_i=E_{P_w}(f_i)$。当$e_i=m_i=0$时，该坐标在当前支撑上不可识别，固定$\delta_i=0$并继续，不能把整个问题判为不可行；当$|e_i-m_i|\leq\varepsilon$时记为“已匹配”；当$e_i,m_i>0$且未匹配时才进入有限一维求根。若$e_i>0,m_i=0$，经验正质量落在模型零支撑上，才是需要报告的支撑冲突；若$e_i=0,m_i>0$，无正则闭式只在$\delta_i\to-\infty$的边界达到，有限精度实现应按预登记规则删除/固定该稀疏坐标或改用正则化，而不是伪造有限根。

IIS的每轮更新提高对数似然下界，但通常比利用联合曲率的拟Newton法慢。它的教学价值在于把“期望不匹配”转化为每个参数的一维修正，并明确说明归一化因子与特征总量为何进入更新方程。

