\begin{AlgorithmContract}{
  input={非空观测序列集合、状态数/允许拓扑、目标$u\in\{\mathrm{ML},\mathrm{MAP}\}$、合法初值及可选Dirichlet先验},
  output={最后合法HMM参数$\lambda$、目标轨迹、完成轮数$r_{\rm done}$、序列E步数$s_{\rm done}$、状态与诊断},
  preconditions={序列符号合法；初值在固定拓扑内概率归一化且目标有限；MAP先验、容差、预算和并列规则合法},
  initialization={$\lambda=\lambda^{(0)},r_{\rm done}=s_{\rm done}=0$并按ML或MAP口径计算$L$},
  loop={每轮只用旧参数对全部序列累计后验计数，再形成ML或MAP候选并计算同口径目标},
  update={全部序列E步、M步行归一化、拓扑和单调目标门禁通过后才原子提交参数},
  domain={$A,B,\pi$位于固定支撑的概率单纯形；后验与期望计数非负有限；选定目标有限},
  failure={非法数据、目标、初值或先验返回$\mathtt{invalid\_input}$；零序列概率、后验/M步归一化、零允许行或目标门禁失败返回$\mathtt{numerical\_failure}$},
  stop={目标相对增量满足容差、轮数预算耗尽或首次失败时停止},
  budget={至多$R_{\max}$个完整Baum--Welch轮；每轮恰好扫描全部$S$条序列},
  status={$\mathtt{numerical\_stop}$、$\mathtt{budget\_stop}$、$\mathtt{invalid\_input}$、$\mathtt{numerical\_failure}$},
  iterations={$r_{\rm done}$计原子提交轮，$s_{\rm done}$计实际完成的单序列前向--后向E步},
  diagnostics={失败$(r,s)$或参数行与E/M/目标阶段、零计数、目标增量、后验变化、ML/MAP口径和预算余量},
  complexity={$S$条平均长$T$序列、$N$状态共$O(r_{\rm done}STN^2)$时间；后验可流式累计}
}
\begin{algorithm}[H]
\SLStudentTallAlgorithmFont
\SetArgSty{textnormal}
\caption{区分ML与MAP目标的Baum--Welch学习}\label{alg:V3-C05-bw}
\KwIn{观测序列$\{O_s\}_{s=1}^S$；状态数与允许拓扑；$u\in\{\mathrm{ML},\mathrm{MAP}\}$；初值$\lambda^{(0)}$}
\KwOut{最后合法$\lambda$、目标轨迹、$r_{\rm done},s_{\rm done}$、$\mathtt{status}$与最终诊断}
\KwData{$R_{\max}\in\mathbb N_0$；$\varepsilon_L>0$；$\tau_{\rm num}\ge0$；MAP时固定Dirichlet参数；固定并列规则}
$\lambda\leftarrow\lambda^{(0)}$，$r_{\rm done}\leftarrow0$，$s_{\rm done}\leftarrow0$，目标轨迹与诊断为空\;
若$S<1$、序列为空或含字典外符号、状态/拓扑/初值非法、$u$非法、MAP先验不合法，或预算、容差、并列规则不合法，则返回当前初值、计数$0$、$\mathtt{invalid\_input}$及字段诊断\;
按$u$计算$L\leftarrow\ell(\lambda)$或$\ell(\lambda)+\log p(\lambda)$；若非有限则返回最后合法初值、$\mathtt{numerical\_failure}$及初始化目标诊断\;
\While{$r_{\rm done}<R_{\max}$}{
  保存$\lambda_{\rm old}\leftarrow\lambda,L_{\rm old}\leftarrow L$，清零临时期望计数\;
  \For{$s\leftarrow1$ \KwTo $S$}{
    只用$\lambda_{\rm old}$执行同域前向--后向；若序列概率为零、后验归一化失败或结果非有限，则返回最后合法$\lambda_{\rm old},L_{\rm old},r_{\rm done},s_{\rm done},\mathtt{numerical\_failure}$，诊断为E步$(r_{\rm done},s)$\;
    把有限$\gamma_1,\sum_t\xi_t$和发射占用加入临时累计量，令$s_{\rm done}\leftarrow s_{\rm done}+1$\;
  }
  若$u=\mathrm{ML}$，按原始期望计数形成$\lambda^+$；任一允许行分母为零时返回最后合法状态与$\mathtt{numerical\_failure}$，诊断为ML M步零计数行\;
  若$u=\mathrm{MAP}$，仅加预登记Dirichlet减一形成$\lambda^+$；候选计数为负、分母非正或先验支撑不一致时返回最后合法状态与$\mathtt{numerical\_failure}$，诊断为MAP M步参数行\;
  保持禁止转移为零并核验$\lambda^+$各行有限、非负、归一化；失败则返回未改动的最后合法状态与$\mathtt{numerical\_failure}$，诊断为候选参数核验\;
  按同一$u$计算$L^+$；若非有限或$L^+<L_{\rm old}-\tau_{\rm num}$，则返回未改动的最后合法状态与$\mathtt{numerical\_failure}$，诊断为目标门禁及新旧值\;
  原子提交$\lambda\leftarrow\lambda^+,L\leftarrow L^+$及轨迹，令$r_{\rm done}\leftarrow r_{\rm done}+1$；记录后验变化与目标增量\;
  \If{$|L-L_{\rm old}|\le\varepsilon_L(1+|L_{\rm old}|)$}{返回最后合法$\lambda,L,r_{\rm done},s_{\rm done},\mathtt{numerical\_stop}$，最终诊断记录目标平台、ML/MAP口径、后验变化及可用固定点残差\;}
}
返回最后合法$\lambda,L,r_{\rm done},s_{\rm done},\mathtt{budget\_stop}$，最终诊断记录轮数预算耗尽与末轮目标增量\;
\end{algorithm}
\end{AlgorithmContract}
\SLRobustImplementationStrip{Baum--Welch的似然小变化只返回$\mathtt{numerical\_stop}$；固定点/KKT残差未核验时不得写作$\mathtt{converged}$，实际耗尽$R_{\max}$才返回$\mathtt{budget\_stop}$。}

\textbf{推导第1步：写出第一分量。}
\[
r=0.7r+0.2(1-r).
\]
\textbf{推导第2步：解线性方程。}$0.5r=0.2$，所以$r=0.4$，候选分布为$\rho=(0.4,0.6)$。

\textbf{推导第3步：回代核验。}
\[
(0.4,0.6)
\begin{pmatrix}0.7&0.3\\0.2&0.8\end{pmatrix}
=(0.4,0.6),
\]
且两个分量非负、和为$1$，故它确为平稳分布。

\phantomsection\label{struct:V5-C01-CH12}

\textbf{推导第1步：写出流入量。}
\[
(\rho A)_j=\sum_i\rho_i a_{ij}.
\]
\textbf{推导第2步：逐边反向。}由细致平衡，
\[
\sum_i\rho_i a_{ij}=\sum_i\rho_j a_{ji}
=\rho_j\sum_i a_{ji}.
\]
\textbf{推导第3步：使用行和。}这里$i$遍历的是矩阵第$j$行的目的状态，所以$\sum_i a_{ji}=1$，于是$(\rho A)_j=\rho_j$。对每个$j$成立，故$\rho A=\rho$。

\begin{warningbox}
细致平衡只保证平稳性。取$A=I_2$和任意严格正概率行向量$\rho=(a,1-a)$，其中$0<a<1$，所有等式$\rho_i a_{ij}=\rho_j a_{ji}$都成立，但两个状态互不可达，链可约，且平稳分布不唯一。再取$f(1)=0,f(2)=1$：从状态$1$出发时路径恒留在$1$，时间平均恒为$0$，而指定分布下的空间平均为$\sum_i\rho_i f(i)=1-a>0$。因此仅有可逆性也不保证无条件时间平均结论、非周期性或从任意初值逐步收敛；不可约性等条件必须另行验证。
\end{warningbox}

\phantomsection\label{struct:V5-C01-CH14}
\textbf{几何解释。}所有$n$维概率分布组成概率单纯形，映射$\rho\mapsto\rho A$把该单纯形映回自身。平稳分布是这个仿射映射的固定点。图\ref{fig:V5-C01-stationary-fixed-point}在两状态概率区间上画出$r\mapsto0.2+0.5r$，固定点$r=0.4$对应$\rho=(0.4,0.6)$。

\textbf{推导第1步：检查概率约束。}$\rho_i\ge0$且$\sum_i\rho_i=D/D=1$。

\textbf{推导第2步：检查每条边。}若$\{i,j\}\in E$，则
\[
\rho_i a_{ij}=\frac{d_i}{D}\frac1{d_i}=\frac1D
=\frac{d_j}{D}\frac1{d_j}=\rho_j a_{ji};
\]
非相邻顶点的两个方向都为$0$。

\textbf{推导第3步：使用细致平衡结论。}候选分布满足式\eqref{eq:V5-C01-detailed-balance}，故
\begin{equation}\label{eq:V5-C01-degree-stationary}
\rho_i=\frac{d_i}{\sum_kd_k}
\end{equation}
是平稳分布。连通性进一步保证它唯一，但若图为二部图，普通逐步分布仍会按奇偶振荡。

图\ref{fig:V5-C01-random-walk}展示三节点路径上的简单游走及其惰性版本。端点度数为$1$、中点度数为$2$，所以平稳分布为$(1/4,\allowbreak 1/2,\allowbreak 1/4)$；加入自环后该分布不变。

\textbf{推导第1步：期望的线性性。}
\[
E(\widehat\mu_N)=\frac1N\sum_{i=1}^NE(Y_i)=\frac1N\cdot N\mu=\mu.
\]
\textbf{推导第2步：独立性消去协方差。}若$\sigma^2=\operatorname{Var}(Y_1)<\infty$，则
\begin{equation}\label{eq:V5-C02-mc-variance}
\operatorname{Var}(\widehat\mu_N)
=\frac1{N^2}\sum_{i=1}^N\operatorname{Var}(Y_i)
+\frac2{N^2}\sum_{i<j}\operatorname{Cov}(Y_i,Y_j)
=\frac{\sigma^2}{N}.
\end{equation}
\textbf{推导第3步：均方误差分解。}任意平方可积估计量$T$满足
\begin{equation}\label{eq:V5-C02-mse-decomposition}
E[(T-\mu)^2]=\operatorname{Var}(T)+\{E(T)-\mu\}^2.
\end{equation}
因此式\eqref{eq:V5-C02-mc-estimator}的均方误差为$\sigma^2/N$，均方根误差为$\sigma/\sqrt N$。这个速率依赖独立同分布和有限方差，不能原样套到相关样本或无限方差情形。

积分改写也需要条件。设$h$在区域$\mathcal D$上可积，$p$是$\mathcal D$上的概率密度。要求
\begin{equation}\label{eq:V5-C02-integral-support}
p(x)=0\Longrightarrow h(x)=0\quad\text{几乎处处},
\qquad \int_{\mathcal D}|h(x)|\,\mathrm dx<\infty.
\end{equation}
在$p(x)>0$处定义$f(x)=h(x)/p(x)$，在$p(x)=0$处定义$f(x)=0$，则
\begin{equation}\label{eq:V5-C02-integral-expectation}
\int_{\mathcal D}h(x)\,\mathrm dx
=\int_{\mathcal D}f(x)p(x)\,\mathrm dx
=E_p[f(X)].
\end{equation}
若还要使用有限方差误差公式，则必须再有
\begin{equation}\label{eq:V5-C02-integral-second-moment}
\int_{\{p>0\}}\frac{h(x)^2}{p(x)}\,\mathrm dx<\infty.
\end{equation}
所以“选任意密度就能计算任意积分”不是正确命题；密度必须覆盖被积函数的非零区域，且比值必须满足相应可积条件。阅读图\ref{fig:V5-C02-mc-integral}时应具体回答：被积函数非零而$p=0$的区域会在哪一步丢失，以及式\eqref{eq:V5-C02-integral-second-moment}为何比一阶积分改写多出一个$1/p$因子。图只表示这两个逻辑接口，不提供随机复算坐标。

\textbf{推导第1步：给出共同流的上界。}
令$c=a\alpha_{xy}=b\alpha_{yx}$。由$0\leq\alpha_{xy},\alpha_{yx}\leq1$，同时有$c\leq a$与$c\leq b$，因而$c\leq\min\{a,b\}$。

\textbf{推导第2步：构造达到上界的双向接受概率。}
当$a,b>0$时取$\alpha_{xy}=\min\{a,b\}/a$及$\alpha_{yx}=\min\{a,b\}/b$；若某一方向流为零，则共同流只能为零，并把由正流指向零反向流的移动确定拒绝。该构造在所有边界情形均不需要计算$0/0$。

\textbf{推导第3步：还原MH接受核。}
在$a>0$的分支，正向接受概率化为$\alpha(x,y)=\min\{1,b/a\}$；代回$a=\widetilde\pi(x)q(x,y)$与$b=\widetilde\pi(y)q(y,x)$即得式\eqref{eq:V5-C03-mh-alpha}。未接受的剩余质量必须并入$x$处拒绝自环，才能得到总质量为$1$的马尔可夫核。

